    INSERT INTO T_TMP_B (FLAG, TXT01, TXT02, TXT03, TXT04, TXT05, TXT06, TXT07, TXT08, TXT09, TXT10, TXT11, TXT12, TXT13, TXT14) 
    VALUES ('PRV_PRD', 'EQUILUMBA', '00001', '11501', 'TORAY ADVANCED MATERIALS KOREA INC.', 'OCASIONAL', NULL, 'EXT', NULL, NULL, '575002005', NULL, NULL, NULL, NULL);
    
    INSERT INTO T_TMP_B (FLAG, TXT01, TXT02, TXT03, TXT04, TXT05, TXT06, TXT07, TXT08, TXT09, TXT10, TXT11, TXT12, TXT13, TXT14) 
    VALUES ('PRV_PRD', 'EQUILUMBA', '00001', '11501', 'TORAY ADVANCED MATERIALS KOREA INC.', 'OCASIONAL', NULL, 'EXT', NULL, NULL, '575002006', NULL, NULL, NULL, NULL);
    
    INSERT INTO T_TMP_B (FLAG, TXT01, TXT02, TXT03, TXT04, TXT05, TXT06, TXT07, TXT08, TXT09, TXT10, TXT11, TXT12, TXT13, TXT14,TXT15,TXT16) 
    SELECT  DISTINCT  'PRV_PRDDS' FLAG,TXT01 USUARIO,TXT02 Compañía,TO_NUMBER(TXT03) COd_Proveedor,TXT04 Proveedor,TXT05 Tipo_Proveedor,TXT06 OC_Reserva,TXT07 Origen_Proveedor,TXT08 PaIs_Proveedor,TXT09 Moneda,TXT10 Cod_Producto,TXT11 Cod_Prod_Proveedor,TXT12 Desc_Prod_Proveedor,TXT13 UM_Prod_Proveedor,TXT14 Tipo_Precio,
        MIN(case TXT05 
            when 'SELECTO' THEN 0
            when 'DESIGNADO' THEN 1
            when 'OBLIGATORIO' THEN 2
            when 'OCASIONAL' THEN 3
        END)OVER(PARTITION BY TO_NUMBER(TXT03)),
        MIN(case TXT01 
            when 'CLOPEZ' THEN 0
            when 'ACARVAJAL' THEN 1
            when 'EQUILUMBA' THEN 2
        END)OVER(PARTITION BY TO_NUMBER(TXT03))
    FROM T_TMP_B 
    WHERE FLAG='PRV_PRD'
    ORDER BY TO_NUMBER(TXT03),TXT10,FLAG;
    DELETE FROM T_TMP_B WHERE FLAG='PRV_PRD';    
 
    UPDATE T_TMP_B SET TXT05 = 
       case TRIM(TXT05) 
        when 'SELECTO' THEN 'SEL'
        when 'DESIGNADO' THEN 'DES'
        when 'OBLIGATORIO' THEN 'OBL'
        when 'OCASIONAL' THEN 'OCS'
    END WHERE FLAG='PRV_PRDDS';
    
    UPDATE T_TMP_B SET TXT15 = 
       case TO_NUMBER(TXT15) 
        when 0 THEN 'SEL'
        when 1 THEN 'DES'
        when 2 THEN 'OBL'
        when 3 THEN 'OCS'
    END WHERE FLAG='PRV_PRDDS';
     
    UPDATE T_TMP_B SET TXT16 = 
           case TO_NUMBER(TXT16) 
            when 0 THEN 'CLOPEZ'
            when 1 THEN 'ACARVAJAL'
            when 2 THEN 'EQUILUMBA'
        END WHERE FLAG='PRV_PRDDS';
    
    UPDATE T_TMP_B SET TXT14 =   case TXT14 when 'FIJO' THEN 'FJ' when 'FORMULA' THEN 'FM' ELSE TXT14 END;
    UPDATE T_TMP_B SET TXT07 = CASE WHEN TXT07 IN ('EXTERIOR','EXT','INTERNACIONAL')THEN 'EXT' WHEN TXT07 IN ('INTERIOR','NAC','NACIONAL')THEN 'NAC' ELSE 'NAC'END;


    UPDATE T_TMP_B SET TXT06 =case TXT05 when 'OCS' THEN 5 ELSE NULL END ;COMMIT;
    
    
END;
/
select FLAG, TXT01, TXT02, TXT03, TXT04, TXT05, TXT06, TXT07, TXT08, TXT09, TXT10, TXT11, TXT12, TXT13, TXT14,TXT15,TXT16 from  T_TMP_B ; WHERE TXT05='OCS' AND PK_COMMONS.F_ESNUMERO(TXT06)!=1;
/
DECLARE 
    V_ID            NUMBER;
    v_pais          varchar2(399);
    v_provincia     varchar2(399);
    v_ciudad        varchar2(399);
    v_parroquia     varchar2(399);
    
    cursor v_cursorprv Is 
        WITH wproveedores AS (
            SELECT
                p.a6an8,
                TRIM(p.A6TRAP)  AS condicion_pago,
                TRIM(p.A6CRRP) AS moneda,
                TRIM(p.a6mnsC) AS codigo_clasificacion,
                TRIM(p.a6mcuP) AS unidad_negocio,
                TRIM(p.a6hold) AS estado_retencion,
                TRIM(p.a6an8r) AS numero_direccion_relacionada,
                nvl(trim(p.A6FRTH),'DAP') as incoterm
            FROM VT_JDE_F0401 p
        ),
        wlibro AS (
            SELECT
                a.aban8,
                TRIM(a.abtax)  AS identificacion,
                TRIM(a.abalph) AS razon_social,
                TRIM(a.abalky) AS clave_alternativa,
                TRIM(a.abdc)   AS descripcion,
                TRIM(a.abat1)  AS tipo_registro,
                TRIM(a.abac01) AS categoria_01,
                TRIM(a.abmcu)  AS unidad_negocio,
                TRIM(a.abtaxc) AS codigo_identificacion_fiscal,
                trim(ABAC03)   as origen,
                TRIM(ABAC21)   AS tipocontribuyenteespecial
            FROM VT_JDE_F0101 a
        ),
        wdireccion AS (
            SELECT *
            FROM (
                SELECT
                    d.alan8,
                    TRIM(d.alctr)  AS pais,TRIM(d.aladds) AS provincia,TRIM(d.alcty1) AS ciudad,
                    TRIM(d.aladdz) AS codigo_postal,
                    TRIM(TRIM(d.aladd1) || ' ' ||TRIM(d.aladd2) || ' ' ||TRIM(d.aladd3) || ' ' ||TRIM(d.aladd4)) AS direccion,
                    ROW_NUMBER() OVER (PARTITION BY d.alan8 ORDER BY d.aleftb DESC, d.aleftf DESC ) AS rn
        
                FROM VT_JDE_F0116 d
            )
            WHERE rn = 1
        ),
        wtelefonos AS (
            SELECT
                t.wpan8,
                MAX( COALESCE( DECODE(t.wpart * t.telefono, NULL, NULL, '(+'||t.wpart||')'||t.telefono), DECODE(t.wparc * t.celular, NULL, NULL, '(+'||t.wparc||')'||t.celular) ) ) telefono,
                MAX( COALESCE( DECODE(t.wparc * t.celular, NULL, NULL, '(+'||t.wparc||')'||t.celular), DECODE(t.wpart * t.telefono, NULL, NULL, '(+'||t.wpart||')'||t.telefono) ) ) celular,
                MAX(t.contacto) contacto
            FROM (
                SELECT
                    t.wpan8,t.wpar1,t.wpphtp,TRIM(t.wpph1), pk_commons.f_esnumero(SUBSTR(TRIM(t.wpph1), 1))esnumero,
                    NVL(CASE WHEN nvl(trim(t.wpphtp),'OFI') IN ('OFI', 'FAX', 'DOM') and nvl(TRIM(t.wpph1),'593') is not null and pk_commons.f_esnumero(SUBSTR(TRIM( REGEXP_REPLACE(t.wpph1, '[^0-9()+]', '')), 1))=1 and pk_commons.f_esnumero(SUBSTR(TRIM(t.wpar1), 1))=1 THEN  to_number(nvl(t.wpar1,'593'))  END,'593') wpart,
                    CASE WHEN nvl(trim(t.wpphtp),'OFI') IN ('OFI', 'FAX', 'DOM') and nvl(TRIM(t.wpph1),'593') is not null and pk_commons.f_esnumero(SUBSTR(TRIM( REGEXP_REPLACE(t.wpph1, '[^0-9()+]', '')), 1))=1 THEN  to_number(SUBSTR(TRIM( REGEXP_REPLACE(t.wpph1, '[^0-9()+]', '')), 1))                                           END telefono,
                    NVL(CASE WHEN nvl(trim(t.wpphtp),'OFI') IN ('CEL')               and nvl(TRIM(t.wpph1),'593') is not null and pk_commons.f_esnumero(SUBSTR(TRIM( REGEXP_REPLACE(t.wpph1, '[^0-9()+]', '')), 1))=1 and pk_commons.f_esnumero(SUBSTR(TRIM(t.wpar1), 1))=1 THEN  to_number(nvl(t.wpar1,'593'))  END,'593') wparc,
                    CASE WHEN nvl(trim(t.wpphtp),'OFI') IN ('CEL')               and nvl(TRIM(t.wpph1),'593') is not null and pk_commons.f_esnumero(SUBSTR(TRIM( REGEXP_REPLACE(t.wpph1, '[^0-9()+]', '')), 1))=1 THEN  to_number(SUBSTR(TRIM( REGEXP_REPLACE(t.wpph1, '[^0-9()+]', '')), 1))                                         END celular,
                    t.wpph1,
                    (nvl(h.wwmlnm, g.wwmlnm))contacto
                FROM      VT_JDE_F0115 t --3957  Filas
                left JOIN VT_JDE_F0111 G ON t.wpan8=g.wwan8 AND g.wwidln=0
                left JOIN VT_JDE_F0111 H ON t.wpan8=H.wwan8 AND H.wwidln=1
                WHERE
                    t.wprck7 IN (1, 2)
                AND WPPH1 IS NOT NULL
            ) t
            group by  t.wpan8
        ),
        wcorreos AS (
            SELECT /*+ MATERIALIZE*/ 
               eaan8 eaan8, 
               JSON_ARRAYAGG(
                    JSON_OBJECT(
                    'tipo' value 
                        CASE NVL(E.EARCK7,1) 
                            WHEN 1 THEN 'PRINCIPAL'WHEN 2 THEN 'DOCUMENTOS'WHEN 3 THEN 'COMUNICADOS'WHEN 4 THEN 'FACTURAS'
                            WHEN 5 THEN 'NOTAS CRÉDITO'WHEN 6 THEN 'PAGOS'WHEN 7 THEN 'RETENCIONES'WHEN 8 THEN 'OTROS'
                        END ,
                    'correo' value TRIM(e.eaemal)
                    )
                    ORDER BY EARCK7
                    RETURNING CLOB
                ) correo_electronico
            FROM     VT_JDE_F01151 e  
            where TRIM(e.eaemal) is not null
            group by eaan8
        ),
        wcontactos AS (
            SELECT
                t.wpan8 wwan8,
                JSON_ARRAYAGG(
                JSON_OBJECT(
                   'tipo' VALUE JSON_ARRAY(
                       CASE NVL(t.wprck7,1)
                           WHEN 1 THEN 'PRINCIPAL'              WHEN 2 THEN 'DOCUMENTOS'   WHEN 3 THEN 'COMUNICADOS'    WHEN 4 THEN 'FACTURAS'
                           WHEN 5 THEN 'NOTAS CRÉDITO'          WHEN 6 THEN 'PAGOS'         WHEN 7 THEN 'RETENCIONES'   WHEN 8 THEN 'OTROS'
                       END
                   ),
                   'persona' VALUE NVL(h.wwmlnm,g.wwmlnm),
                   'cargo' VALUE 
                            CASE NVL(t.wprck7,1)
                                WHEN 1 THEN 'PRINCIPAL'              WHEN 2 THEN 'DOCUMENTOS'   WHEN 3 THEN 'COMUNICADOS'    WHEN 4 THEN 'FACTURAS'
                                WHEN 5 THEN 'NOTAS CRÉDITO'     WHEN 6 THEN 'PAGOS'         WHEN 7 THEN 'RETENCIONES'   WHEN 8 THEN 'OTROS'
                            END,
                    'telefono' VALUE SUBSTR(REGEXP_REPLACE('(+'||TRIM(t.wpar1)||')'||TRIM(t.wpph1),'[^0-9()+]',''),1,20),
                    'correo' VALUE NVL(TRIM(e.eaemal),
                                CASE NVL(t.wprck7,1)
                                    WHEN 1 THEN 'principal'     WHEN 2 THEN 'documentos'   WHEN 3 THEN 'comunicados'    WHEN 4 THEN 'facturas'
                                    WHEN 5 THEN 'notas_credito' WHEN 6 THEN 'pagos'         WHEN 7 THEN 'retenciones'   WHEN 8 THEN 'otros'
                                END||'@gmail.com'
                               )
                    )
                   ORDER BY t.wprck7
                   RETURNING CLOB
               ) personas_contacto
            FROM VT_JDE_F0115 t
            LEFT JOIN VT_JDE_F0111 g ON t.wpan8=g.wwan8 AND g.wwidln=0
            LEFT JOIN VT_JDE_F0111 h ON t.wpan8=h.wwan8 AND h.wwidln=1
            LEFT JOIN VT_JDE_F01151 e ON t.wpan8=e.eaan8 AND NVL(t.wprck7,1)=NVL(e.earck7,1)
            GROUP BY t.wpan8
        ),        
        wbancos AS (
            SELECT IBAN8, BANCO, CODIGO_SWIFT, TIPO_CUENTA, NUMERO_CUENTA, BENEFICIARIO
            FROM (
                SELECT    
                    b.IBAN8,
                    upper(TRIM(J.DRDL01)) AS banco,
                    upper(TRIM(b.IBSWFT)) AS codigo_swift,
                    --upper(TRIM(b.IBCKSV)) AS tipo_cuenta,
                    case when  b.IBCKSV='1' then 'AHORRO' ELSE  'CORRIENTE'  END AS tipo_cuenta,
                    upper(TRIM(b.IBGENKEY)) AS numero_cuenta,
                    TXT04 AS beneficiario,
                    ROW_NUMBER() OVER (
                                        PARTITION BY b.IBAN8
                                        ORDER BY b.IBAN8, 
                                        b.IBALPH DESC,
                                                 b.IBSWFT DESC,
                                                 b.IBCKSV DESC
                                    ) AS rn
                FROM vt_jde_f76e0030 b JOIN t_tmp_b T ON b.IBAN8=TO_NUMBER(TXT03)
                JOIN vt_jde_udcjde J ON DRSY='76E' AND DRRT='BK' AND IBAAT1=DRKY 
            ) WHERE RN=1
        )
        ,wtmpb as (
            SELECT /*+ MATERIALIZE */
               TRIM(txt02) compania,
               TO_NUMBER(txt03) prvan8,
               TRIM(txt15) tipo_proveedor,
               trim(upper(TXT16)) usuario 
            FROM t_tmp_b
            WHERE VALIDATE_CONVERSION(txt03 AS NUMBER) = 1
            GROUP BY
               TRIM(txt02),
               TO_NUMBER(txt03),
               TRIM(txt15),
               trim(upper(TXT16)) 
        )--select * from wtmpb; 
        ,resultado as (   
            SELECT
                /* 00 */ ml.compania as compania,
                /* 01 */ tipo_proveedor AS tipoproveedor,
                /* 02 */ 'ACTIVO' AS estado,
                /* 03 */ NULL   AS idflujoaprobacion,
                /* 04 */ p.a6an8 AS codproveedor,
                /* 05 */ DRDL02 AS tipoidentificacion,
                /* 06 */ l.identificacion AS numeroidentificacion,
                /* 07 */ l.razon_social AS razonsocial,
                /* 08 */ l.descripcion AS nombrecomercial,
                /* 09 */ l.razon_social AS representantelegal,
                /* 10 */ 'S'  AS aplicagrupozml,
                /* 11 */ 'N'  AS reservaoc,
                /* 12 */ 0  AS cantidadocs,
                /* 13 */ 'N'  AS obligadocontabilidad,
                /* 14 */ 'S'  AS contribuyenteespecial,
                /* 15 */ origen  AS origen,
                /* 16 */ d.pais  AS pais,
                /* 17 */ d.provincia  AS provincia,
                /* 18 */ d.ciudad  AS ciudad,
                /* 19 */ CAST(NULL AS VARCHAR2(100))  AS parroquia,
                /* 20 */ d.codigo_postal  AS codigopostal,
                /* 21 */ d.direccion  AS direccion,
                /* 22 */ nvl(t.telefono,'(+593)99999999')  AS telefono,
                /* 23 */ nvl(t.celular,'(+593)99999999')  AS celular,
                /* 24 */ e.correo_electronico  AS correoelectronico,
                /* 25 */ c.personas_contacto  AS personascontacto,
                /* 26 */ p.condicion_pago  AS plazopago,
                /* 27 */ CAST(incoterm AS VARCHAR2(30))  AS incoterm,
                /* 28 */ b.banco  AS banco,
                /* 29 */ b.codigo_swift  AS codigoswift,
                /* 30 */ b.tipo_cuenta  AS tipocuenta,
                /* 31 */ b.numero_cuenta  AS numerocuenta,
                /* 32 */ b.beneficiario  AS beneficiario,
                /* 33 */ '[{"usuario":"'||usuario||'","comentario":"Carga Masiva en el cambio de proveedores","fecha":"'||to_char(systimestamp,'dd/mm/yyyy HH24:MI:SS')||'"}]' AS comentarios,
                /* 34 */ CAST(NULL AS VARCHAR2(4000))  AS adjuntos,
                /* 35 */ l.CODIGO_IDENTIFICACION_FISCAL  AS tipopersonasociedad,
                /* 36 */ l.unidad_negocio  AS unidadnegocio,
                /* 37 */ CAST(NULL AS VARCHAR2(100))  AS tipocontribuyenteespecial,--AC21
                /* 38 */ CAST(NULL AS NUMBER)  AS idrutaaprobacion,
                /* 39 */ p.moneda  AS moneda,
                /* 40 */ CAST(NULL AS NUMBER)  AS cantidadocsreal,
                /* 41 */ CAST(NULL AS DATE) as fechafinrel,
                /* 42 */ usuario as usuario,
                /* 43 */ sysdate as fecharegistro
                
            FROM wproveedores p
            inner join wtmpb    ml ON p.a6an8=ML.prvan8
            INNER JOIN wlibro    l ON p.a6an8= l.aban8 
            LEFT JOIN wdireccion d ON p.a6an8= d.alan8 
            LEFT JOIN wtelefonos t ON p.a6an8= t.wpan8 
            LEFT JOIN wcorreos   e ON p.a6an8= e.eaan8 
            LEFT JOIN wcontactos c ON p.a6an8= c.wwan8 
            LEFT JOIN wbancos    b ON p.a6an8= b.IBAN8 
            left join data.VT_JDE_udcjde@zaip u  on DRSY='H00' AND DRRT='TA' AND DRKY= l.codigo_identificacion_fiscal
        )
        SELECT l.* 
        FROM resultado l;
begin
    BEGIN
        if not pk_corp_commons.f_isproduccion then
            delete DATA.t_comp_negociacion; commit;
            delete from t_secuencia where key ='data.t_comp_negociacion';commit;
            
            delete DATA.t_comp_negociaciondet; commit;
            delete from t_secuencia where key ='data.t_comp_negociaciondet';commit;
            
            delete DATA.t_corp_proveedor; commit;
            delete from t_secuencia where key ='data.t_corp_proveedor';commit;
            DBMS_OUTPUT.PUT_LINE('borrado');
        end if;
    END;
    for prv in  v_cursorprv 
    LOOP
        begin
            SELECT IDLOCATION into v_pais FROM T_APEX_LOCATIONS WHERE ADMLEVEL = 'ADM0' and trim( upper(CODELOCATION))=trim(prv.PAIS) AND ACTIVO = 1 ;
        exception when others then 
             v_pais:=null;
        end ;
        begin
            SELECT IDLOCATION into v_provincia FROM T_APEX_LOCATIONS WHERE ADMLEVEL = 'ADM1' AND IDPARENT = v_pais and trim( upper(CODELOCATION))=trim(prv.PROVINCIA) AND ACTIVO = 1 ;
        exception when others then 
            v_provincia:=null;
        end ;

        v_ciudad:='';
        v_parroquia:='';
        DBMS_OUTPUT.PUT_LINE('prv.COMENTARIOS:'||prv.COMENTARIOS);
        INSERT INTO t_corp_proveedor (
            compania,tipoproveedor,estado,codproveedor,tipoidentificacion,numeroidentificacion,razonsocial,nombrecomercial,representantelegal,
            aplicagrupozml,reservaoc,cantidadocs,obligadocontabilidad,contribuyenteespecial,origen,
            pais,provincia,ciudad,parroquia,codigopostal,direccion,telefono,celular,correoelectronico,personascontacto,plazopago,incoterm,banco,codigoswift,tipocuenta,
            numerocuenta,beneficiario,comentarios,adjuntos,tipopersonasociedad,unidadnegocio,tipocontribuyenteespecial,idrutaaprobacion,moneda,cantidadocsreal,fechafinrel
        ) VALUES (
            prv.compania,prv.TIPOPROVEEDOR, prv.ESTADO, prv.CODPROVEEDOR, prv.TIPOIDENTIFICACION, prv.NUMEROIDENTIFICACION, prv.RAZONSOCIAL, prv.NOMBRECOMERCIAL, prv.REPRESENTANTELEGAL, 
            prv.APLICAGRUPOZML, prv.RESERVAOC, prv.CANTIDADOCS, prv.OBLIGADOCONTABILIDAD, prv.CONTRIBUYENTEESPECIAL, prv.ORIGEN, 
            v_pais, v_provincia, v_ciudad, v_parroquia, prv.CODIGOPOSTAL, prv.DIRECCION, prv.TELEFONO, prv.CELULAR, prv.CORREOELECTRONICO, prv.PERSONASCONTACTO, prv.PLAZOPAGO, prv.INCOTERM, prv.BANCO, prv.CODIGOSWIFT, prv.TIPOCUENTA, 
            prv.NUMEROCUENTA, prv.BENEFICIARIO, prv.COMENTARIOS, prv.ADJUNTOS, prv.TIPOPERSONASOCIEDAD, prv.UNIDADNEGOCIO, prv.TIPOCONTRIBUYENTEESPECIAL, prv.IDRUTAAPROBACION, prv.MONEDA, prv.CANTIDADOCSREAL, prv.FECHAFINREL
            
        ) returning id into v_id;

        INSERT INTO t_comp_negociaciondet(IDCAB, IDPGR, COMPANIA, ESTADOGEN, ESTADOREL, ESTADOMTX, 
            UNIDADNEGOCIOAPR, UNIDADNEGOCIOGTO, DIRECCIONENVIO, IDRUTAAPROBACION, 
            IDFLUJOAPROBACION, CODPROVEEDOR, TIPOPROVEEDOR, TIPOPRECIO, ACUMCANT, IDFORMULA, VIGDESDE, VIGHASTA, 
            TOLMIN, TOLMAX, 
            CODPRODUCTOERP, CODPRODUCTOPRV, DSCPRODUCTOPRV, 
            UDMPRODUCTOPRV, MONEDA, TIEMPOENTREGA, PLAZOPAGO, INCOTERM, CANTDESDE, CANTHASTA, CANTMAXIMA, PRECIO, DESCRIPCION, IDCODPROVEEDOR, 
            CODTIPOPRODUCTO, CODCATEGORIA, CODSUBCATEGORIA, CANTIDADOCSREAL, CANTIDADOCS
        )
        SELECT  
            null IDCAB, null IDPGR, PRV.compania COMPANIA,'ACTIVO' ESTADOGEN, 'APROBADO' ESTADOREL,NULL ESTADOMTX, 
            null UNIDADNEGOCIOAPR, null UNIDADNEGOCIOGTO, null DIRECCIONENVIO, null IDRUTAAPROBACION, 
            null IDFLUJOAPROBACION, TO_NUMBER(TXT03) CODPROVEEDOR,TXT05 TIPOPROVEEDOR, NULL TIPOPRECIO, NULL ACUMCANT, NULL IDFORMULA, NULL VIGDESDE, NULL VIGHASTA, 
            NULL TOLMIN, NULL TOLMAX, 
            TXT10 CODPRODUCTOERP,NULL CODPRODUCTOPRV,NULL DSCPRODUCTOPRV,NULL UDMPRODUCTOPRV, 
            PRV.MONEDA MONEDA, 0 TIEMPOENTREGA, PRV.PLAZOPAGO PLAZOPAGO, PRV.INCOTERM INCOTERM, 0 CANTDESDE, 0 CANTHASTA, 0 CANTMAXIMA, 0 PRECIO, NULL DESCRIPCION, V_ID IDCODPROVEEDOR, 
            CODTIPOINVENTARIO CODTIPOPRODUCTO, CODCATEGORIA CODCATEGORIA, CODSUBCATEGORIA CODSUBCATEGORIA, TXT06 CANTIDADOCSREAL, TXT06 CANTIDADOCS 
        FROM data.T_TMP_b B
        JOIN vt_jde_productos P ON TXT10= codigoproducto
        WHERE TO_NUMBER(TXT03)=  PRV.CODPROVEEDOR;
        
        INSERT INTO t_comp_negociaciondet(IDCAB, IDPGR, COMPANIA, ESTADOGEN, ESTADOREL, ESTADOMTX, UNIDADNEGOCIOAPR, UNIDADNEGOCIOGTO, DIRECCIONENVIO, IDRUTAAPROBACION, IDFLUJOAPROBACION, CODPROVEEDOR, TIPOPROVEEDOR, TIPOPRECIO, ACUMCANT, IDFORMULA, VIGDESDE, VIGHASTA, TOLMIN, TOLMAX, CODPRODUCTOERP, CODPRODUCTOPRV, DSCPRODUCTOPRV, UDMPRODUCTOPRV, MONEDA, TIEMPOENTREGA, PLAZOPAGO, INCOTERM, CANTDESDE, CANTHASTA, CANTMAXIMA, PRECIO, DESCRIPCION, IDCODPROVEEDOR, CODTIPOPRODUCTO, CODCATEGORIA, CODSUBCATEGORIA, CANTIDADOCSREAL, CANTIDADOCS)
        select 
            null IDCAB, null IDPGR, prv.compania COMPANIA,'ACTIVO' ESTADOGEN, 'APROBADO' ESTADOREL,'APROBADO' ESTADOMTX, 
            null UNIDADNEGOCIOAPR, null UNIDADNEGOCIOGTO, null DIRECCIONENVIO, null IDRUTAAPROBACION, 
            null IDFLUJOAPROBACION, TO_NUMBER(TXT03) CODPROVEEDOR,TXT05 TIPOPROVEEDOR, case TXT14 when 'FIJO' THEN 'FJ' when 'FORMULA' THEN 'FM' ELSE c.TIPOPRECIO END TIPOPRECIO, null ACUMCANT, c.FORMULA IDFORMULA, 
            NULL VIGDESDE, NULL VIGHASTA, 
            NULL TOLMIN, NULL TOLMAX, 
            TXT10 CODPRODUCTOERP,d.CODPRODUCTOPRV CODPRODUCTOPRV,d.DESPRODUCTOPRV DSCPRODUCTOPRV,d.UMPRODUCTOPRV UDMPRODUCTOPRV, 
            prv.MONEDA MONEDA, d.TIEMPOENTREGA TIEMPOENTREGA, d.FORMAPAGO PLAZOPAGO, d.INCOTERM INCOTERM, 0 CANTDESDE, 0 CANTHASTA, 0 CANTMAXIMA, d.PRECIO PRECIO, 
            NULL DESCRIPCION, V_ID IDCODPROVEEDOR, 
            CODTIPOINVENTARIO CODTIPOPRODUCTO, CODCATEGORIA CODCATEGORIA, CODSUBCATEGORIA CODSUBCATEGORIA, TXT06 CANTIDADOCSREAL, TXT06 CANTIDADOCS 
        from 
             data.t_comp_negociacion@zaip n
        join data.t_comp_negociacioncab@zaip c on n.id=c.IDNEG
        join data.t_comp_negociaciondet@zaip d on c.id =d.idcab--3851
        JOIN data.vt_jde_productos@zaip P ON  CODIGOCORTO=d.CODPRODUCTO
        join  t_tmp_b b on n.CODESQUEMA=TO_NUMBER(TXT03) and to_char(p.CODIGOPRODUCTO)=TXT10
        where sysdate between VIGENCIADESDE and  VIGENCIAHASTA
        and TO_NUMBER(TXT03)=  PRV.CODPROVEEDOR;
        commit;        
        update t_corp_proveedor set USERCREA=prv.usuario,fechcrea=prv.fecharegistro where ID= v_id;
        update t_comp_negociaciondet set USERCREA=prv.usuario,fechcrea=prv.fecharegistro  where IDCODPROVEEDOR= v_id;
    END LOOP;
    COMMIT;
end;
/ 

SELECT * FROM t_corp_proveedor;
SELECT * FROM t_comp_negociacion;
SELECT * FROM t_comp_negociaciondet;
SELECT length(IBGENKEY),f.* FROM vt_jde_f76e0030 f order by 1 desc;


